   136→func (s *Service) onBlockBatch(ctx context.Context, blks []consensusblocks.ROBlock, avs das.AvailabilityStore) error {
   137→	ctx, span := trace.StartSpan(ctx, "blockChain.onBlockBatch")
   138→	defer span.End()
   139→
   140→	if len(blks) == 0 {
   141→		return errors.New("no blocks provided")
   142→	}
   143→
   144→	if err := consensusblocks.BeaconBlockIsNil(blks[0]); err != nil {
   145→		return invalidBlock{error: err}
   146→	}
   147→	b := blks[0].Block()
   148→
   149→	// Retrieve incoming block's pre state.
   150→	if err := s.verifyBlkPreState(ctx, b.ParentRoot()); err != nil {
   151→		return err
   152→	}
   153→	preState, err := s.cfg.StateGen.StateByRootInitialSync(ctx, b.ParentRoot())
   154→	if err != nil {
   155→		return err
   156→	}
   157→	if preState == nil || preState.IsNil() {
   158→		return fmt.Errorf("nil pre state for slot %d", b.Slot())
   159→	}
   160→
   161→	// Fill in missing blocks
   162→	if err := s.fillInForkChoiceMissingBlocks(ctx, blks[0], preState.FinalizedCheckpoint(), preState.CurrentJustifiedCheckpoint()); err != nil {
   163→		return errors.Wrap(err, "could not fill in missing blocks to forkchoice")
   164→	}
   165→
   166→	jCheckpoints := make([]*ethpb.Checkpoint, len(blks))
   167→	fCheckpoints := make([]*ethpb.Checkpoint, len(blks))
   168→	sigSet := bls.NewSet()
   169→	type versionAndHeader struct {
   170→		version int
   171→		header  interfaces.ExecutionData
   172→	}
   173→	preVersionAndHeaders := make([]*versionAndHeader, len(blks))
   174→	postVersionAndHeaders := make([]*versionAndHeader, len(blks))
   175→	var set *bls.SignatureBatch
   176→	boundaries := make(map[[32]byte]state.BeaconState)
   177→	for i, b := range blks {
   178→		if features.BlacklistedBlock(b.Root()) {
   179→			return errBlacklistedRoot
   180→		}
   181→		v, h, err := getStateVersionAndPayload(preState)
   182→		if err != nil {
   183→			return err
   184→		}
   185→		preVersionAndHeaders[i] = &versionAndHeader{
   186→			version: v,
   187→			header:  h,
   188→		}
   189→
   190→		set, preState, err = transition.ExecuteStateTransitionNoVerifyAnySig(ctx, preState, b)
   191→		if err != nil {
   192→			return invalidBlock{error: err}
   193→		}
   194→		// Save potential boundary states.
   195→		if slots.IsEpochStart(preState.Slot()) {
   196→			boundaries[b.Root()] = preState.Copy()
   197→		}
   198→		jCheckpoints[i] = preState.CurrentJustifiedCheckpoint()
   199→		fCheckpoints[i] = preState.FinalizedCheckpoint()
   200→
   201→		v, h, err = getStateVersionAndPayload(preState)
   202→		if err != nil {
   203→			return err
   204→		}
   205→		postVersionAndHeaders[i] = &versionAndHeader{
   206→			version: v,
   207→			header:  h,
   208→		}
   209→		sigSet.Join(set)
   210→	}
   211→
   212→	var verify bool
   213→	if features.Get().EnableVerboseSigVerification {
   214→		verify, err = sigSet.VerifyVerbosely()
   215→	} else {
   216→		verify, err = sigSet.Verify()
   217→	}
   218→	if err != nil {
   219→		return invalidBlock{error: err}
   220→	}
   221→	if !verify {
   222→		return errors.New("batch block signature verification failed")
   223→	}
   224→
   225→	// blocks have been verified, save them and call the engine
   226→	pendingNodes := make([]*forkchoicetypes.BlockAndCheckpoints, len(blks))
   227→	var isValidPayload bool
   228→	for i, b := range blks {
   229→		root := b.Root()
   230→		isValidPayload, err = s.notifyNewPayload(ctx,
   231→			postVersionAndHeaders[i].version,
   232→			postVersionAndHeaders[i].header, b)
   233→		if err != nil {
   234→			return s.handleInvalidExecutionError(ctx, err, root, b.Block().ParentRoot())
   235→		}
   236→		if isValidPayload {
   237→			if err := s.validateMergeTransitionBlock(ctx, preVersionAndHeaders[i].version,
   238→				preVersionAndHeaders[i].header, b); err != nil {
   239→				return err
   240→			}
   241→		}
   242→
   243→		if err := s.areSidecarsAvailable(ctx, avs, b); err != nil {
   244→			return errors.Wrapf(err, "could not validate sidecar availability for block %#x at slot %d", b.Root(), b.Block().Slot())
   245→		}
   246→
   247→		args := &forkchoicetypes.BlockAndCheckpoints{Block: b,
   248→			JustifiedCheckpoint: jCheckpoints[i],
   249→			FinalizedCheckpoint: fCheckpoints[i]}
   250→		pendingNodes[len(blks)-i-1] = args
   251→		if err := s.saveInitSyncBlock(ctx, root, b); err != nil {
   252→			tracing.AnnotateError(span, err)
   253→			return err
   254→		}
   255→		if err := s.cfg.BeaconDB.SaveStateSummary(ctx, &ethpb.StateSummary{
   256→			Slot: b.Block().Slot(),
   257→			Root: root[:],
   258→		}); err != nil {
   259→			tracing.AnnotateError(span, err)
   260→			return err
   261→		}
   262→		if i > 0 && jCheckpoints[i].Epoch > jCheckpoints[i-1].Epoch {
   263→			if err := s.cfg.BeaconDB.SaveJustifiedCheckpoint(ctx, jCheckpoints[i]); err != nil {
   264→				tracing.AnnotateError(span, err)
   265→				return err
   266→			}
   267→		}
   268→		if i > 0 && fCheckpoints[i].Epoch > fCheckpoints[i-1].Epoch {
   269→			if err := s.updateFinalized(ctx, fCheckpoints[i]); err != nil {
   270→				tracing.AnnotateError(span, err)
   271→				return err
   272→			}
   273→		}
   274→	}
   275→	// Save boundary states that will be useful for forkchoice
   276→	for r, st := range boundaries {
   277→		if err := s.cfg.StateGen.SaveState(ctx, r, st); err != nil {
   278→			return err
   279→		}
   280→	}
   281→	lastB := blks[len(blks)-1]
   282→	lastBR := lastB.Root()
   283→	// Also saves the last post state which to be used as pre state for the next batch.
   284→	if err := s.cfg.StateGen.SaveState(ctx, lastBR, preState); err != nil {
   285→		return err
   286→	}
   287→	// Insert all nodes but the last one to forkchoice
   288→	if err := s.cfg.ForkChoiceStore.InsertChain(ctx, pendingNodes); err != nil {
   289→		return errors.Wrap(err, "could not insert batch to forkchoice")
   290→	}
   291→	// Insert the last block to forkchoice
   292→	if err := s.cfg.ForkChoiceStore.InsertNode(ctx, preState, lastB); err != nil {
   293→		return errors.Wrap(err, "could not insert last block in batch to forkchoice")
   294→	}
   295→	// Set their optimistic status
   296→	if isValidPayload {
   297→		if err := s.cfg.ForkChoiceStore.SetOptimisticToValid(ctx, lastBR); err != nil {
   298→			return errors.Wrap(err, "could not set optimistic block to valid")
   299→		}
   300→	}
   301→	arg := &fcuConfig{
   302→		headState: preState,
   303→		headRoot:  lastBR,
   304→		headBlock: lastB,
   305→	}
   306→	if _, err := s.notifyForkchoiceUpdate(ctx, arg); err != nil {
   307→		return err
   308→	}
   309→	return s.saveHeadNoDB(ctx, lastB, lastBR, preState, !isValidPayload)
   310→}
