   453→// pruneAttsFromPool removes these attestations from the attestation pool
   454→// which are covered by attestations from the received block.
   455→func (s *Service) pruneAttsFromPool(ctx context.Context, headState state.BeaconState, headBlock interfaces.ReadOnlySignedBeaconBlock) {
   456→	for _, att := range headBlock.Block().Body().Attestations() {
   457→		if err := s.pruneCoveredAttsFromPool(ctx, headState, att); err != nil {
   458→			log.WithError(err).Warn("Could not prune attestations covered by a received block's attestation")
   459→		}
   460→	}
   461→}
   462→
   463→func (s *Service) pruneCoveredAttsFromPool(ctx context.Context, headState state.BeaconState, att ethpb.Att) error {
   464→	switch {
   465→	case !att.IsAggregated():
   466→		return s.cfg.AttPool.DeleteUnaggregatedAttestation(att)
   467→	case att.Version() == version.Phase0:
   468→		if features.Get().EnableExperimentalAttestationPool {
   469→			return errors.Wrap(s.cfg.AttestationCache.DeleteCovered(att), "could not delete covered attestation")
   470→		}
   471→		return errors.Wrap(s.cfg.AttPool.DeleteAggregatedAttestation(att), "could not delete aggregated attestation")
   472→	default:
   473→		return s.pruneCoveredElectraAttsFromPool(ctx, headState, att)
   474→	}
   475→}
   476→
   477→// pruneCoveredElectraAttsFromPool handles removing aggregated Electra attestations from the pool after receiving a block.
   478→// Because in Electra block attestations can combine aggregates for multiple committees, comparing attestation bits
   479→// of a block attestation with attestations bits of an aggregate can cause unexpected results, leading to covered
   480→// aggregates not being removed from the pool.
   481→//
   482→// To make sure aggregates are removed, we decompose the block attestation into dummy aggregates, with each
   483→// aggregate accounting for one committee. This allows us to compare aggregates in the same way it's done for
   484→// Phase0. Even though we can't provide a valid signature for the dummy aggregate, it does not matter because
   485→// signatures play no part in pruning attestations.
   486→func (s *Service) pruneCoveredElectraAttsFromPool(ctx context.Context, headState state.BeaconState, att ethpb.Att) error {
   487→	if att.Version() == version.Phase0 {
   488→		log.Error("Called pruneCoveredElectraAttsFromPool with a Phase0 attestation")
   489→		return nil
   490→	}
   491→
   492→	// We don't want to recompute committees. If they are not cached already,
   493→	// we allow attestations to stay in the pool. If these attestations are
   494→	// included in a later block, they will be redundant. But given that
   495→	// they were not cached in the first place, it's unlikely that they
   496→	// will be chosen into a block.
